mapper.select:
SELECT 
FROM task


        AND status = #{status}


        AND priority = #{priority}


        AND project_id = #{projectId}


        AND creator_id = #{creatorId}


        AND handler_id = #{handlerId}


        AND (title ILIKE '%' || #{keyword} || '%'
        OR description ILIKE '%' || #{keyword} || '%')


ORDER BY created_at DESC
